import{_ as d,o as e,c as o,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"紹介","description":"","frontmatter":{"title":"紹介","order":1},"headers":[],"relativePath":"ja/latest/web-tool/guide.md","filePath":"ja/latest/web-tool/guide.md","lastUpdated":1788455378000}'),a={name:"ja/latest/web-tool/guide.md"};function l(i,t,s,h,c,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="konado-webtool" tabindex="-1">Konado WebTool <a class="header-anchor" href="#konado-webtool" aria-label="Permalink to &quot;Konado WebTool&quot;">​</a></h1><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>Konado WebTool は、Konado プロジェクトに Web プラットフォーム向け開発ツールサポートを提供するプラグインです。Godot 4.x は Web プラットフォーム上でデフォルトですべてのキーボードショートカットを捕捉して無効化するため、F12 や F5 などのブラウザ開発者ツールのショートカットが正常に使えません。このプラグインはその問題を解決し、Web プラットフォーム上で一般的なブラウザ開発者ツールのショートカットを使えるようにして、Web 環境でのデバッグと開発を容易にします。</p><h2 id="動作原理" tabindex="-1">動作原理 <a class="header-anchor" href="#動作原理" aria-label="Permalink to &quot;動作原理&quot;">​</a></h2><p>Konado WebTool は Web プラットフォーム上で JavaScript コードを注入し、ショートカットを通過させます。処理内容は次のとおりです。</p><ol><li>現在のプラットフォームが Web かどうかを検出します</li><li>Web プラットフォームで開発者ツールサポートが有効な場合、ショートカット処理コードを注入します</li><li>設定に基づいて許可するショートカット一覧を動的に構築します</li><li>ブラウザのデフォルト動作を維持したまま、許可されたショートカットが Godot へ伝播するのを止めます</li></ol><h3 id="他の解決策との比較" tabindex="-1">他の解決策との比較 <a class="header-anchor" href="#他の解決策との比較" aria-label="Permalink to &quot;他の解決策との比較&quot;">​</a></h3><table tabindex="0"><thead><tr><th>解決策</th><th>利点</th><th>欠点</th></tr></thead><tbody><tr><td>Konado WebTool</td><td>簡単に使える、設定しやすい、保守しやすい</td><td>明確な欠点なし</td></tr><tr><td>エクスポートテンプレートを手動修正</td><td>完全に制御できる</td><td>技術要件が高く、頻繁な更新が必要</td></tr><tr><td>開発環境を切り替える</td><td>デスクトッププラットフォームでデバッグ可能</td><td>Web プラットフォーム固有の問題を捕捉できない</td></tr></tbody></table><h2 id="対応するブラウザショートカット" tabindex="-1">対応するブラウザショートカット <a class="header-anchor" href="#対応するブラウザショートカット" aria-label="Permalink to &quot;対応するブラウザショートカット&quot;">​</a></h2><p>これらのショートカット仕様は、Chrome、Firefox、Edge など主要ブラウザの開発者ツール標準ショートカットに基づき、各ブラウザの公式ドキュメントを参照しています。</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Tools/Keyboard_shortcuts" target="_blank" rel="noreferrer">Firefox DevTools</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools-guide-chromium/shortcuts/" target="_blank" rel="noreferrer">Edge DevTools</a></li><li><a href="https://developer.chrome.com/docs/devtools/shortcuts/" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li><a href="https://webkit.org/web-inspector/keyboard-shortcuts/" target="_blank" rel="noreferrer">Safari DevTools（WebKit）</a></li></ul><table tabindex="0"><thead><tr><th>ショートカット</th><th>機能</th><th>有効化オプション</th></tr></thead><tbody><tr><td>F12</td><td>開発者ツールを開く</td><td><code>enable_f12</code></td></tr><tr><td>F5</td><td>ページを再読み込み</td><td><code>enable_f5</code></td></tr><tr><td>F11</td><td>フルスクリーン切り替え</td><td><code>enable_f11</code></td></tr><tr><td>Ctrl+Shift+I (Win/Linux) / Cmd+Opt+I (Mac)</td><td>Elements パネルを開く</td><td><code>enable_ctrl_shift_i</code></td></tr><tr><td>Ctrl+Shift+J (Win/Linux) / Cmd+Opt+J (Mac)</td><td>Console を開く</td><td><code>enable_ctrl_shift_j</code></td></tr><tr><td>Ctrl+Shift+C (Win/Linux) / Cmd+Shift+C (Mac)</td><td>要素検査モード</td><td><code>enable_ctrl_shift_c</code></td></tr><tr><td>Ctrl+U (Win/Linux) / Cmd+U (Mac)</td><td>ページソースを表示</td><td><code>enable_ctrl_u</code></td></tr><tr><td>Ctrl+R (Win/Linux) / Cmd+R (Mac)</td><td>ページを再読み込み</td><td><code>enable_ctrl_r</code></td></tr></tbody></table><h2 id="設定オプション" tabindex="-1">設定オプション <a class="header-anchor" href="#設定オプション" aria-label="Permalink to &quot;設定オプション&quot;">​</a></h2><p>自動読み込みされる <code>KonadoWebTool</code> ノードで、以下のプロパティを設定できます。</p><table tabindex="0"><thead><tr><th>プロパティ</th><th>型</th><th>デフォルト</th><th>説明</th></tr></thead><tbody><tr><td><code>developer_shortcuts_enabled</code></td><td>bool</td><td>true</td><td>Web 開発者ツールショートカットの通過を有効にするか</td></tr><tr><td><code>allow_in_release</code></td><td>bool</td><td>false</td><td>リリースエクスポートでショートカットの通過を有効にするか</td></tr><tr><td><code>enable_f12</code></td><td>bool</td><td>true</td><td>F12 ショートカットを有効にするか</td></tr><tr><td><code>enable_f5</code></td><td>bool</td><td>true</td><td>F5 ショートカットを有効にするか</td></tr><tr><td><code>enable_f11</code></td><td>bool</td><td>true</td><td>F11 ショートカットを有効にするか</td></tr><tr><td><code>enable_ctrl_shift_i</code></td><td>bool</td><td>true</td><td>Ctrl+Shift+I ショートカットを有効にするか</td></tr><tr><td><code>enable_ctrl_shift_j</code></td><td>bool</td><td>true</td><td>Ctrl+Shift+J ショートカットを有効にするか</td></tr><tr><td><code>enable_ctrl_shift_c</code></td><td>bool</td><td>true</td><td>Ctrl+Shift+C ショートカットを有効にするか</td></tr><tr><td><code>enable_ctrl_u</code></td><td>bool</td><td>true</td><td>Ctrl+U ショートカットを有効にするか</td></tr><tr><td><code>enable_ctrl_r</code></td><td>bool</td><td>true</td><td>Ctrl+R ショートカットを有効にするか</td></tr></tbody></table><p>本番環境でデバッグ用の入口が公開されないように、リリースエクスポートではデフォルトでショートカットハンドラーをインストールしません。実行時にプロパティを変更した場合は、次の呼び出しで設定を反映します。</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoWebTool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refresh_shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>',17)])])}const p=d(a,[["render",l]]);export{_ as __pageData,p as default};
